def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    # Find the compact multicolored object, excluding the repeated marker color.
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    marker = min((x for x in counts if x != bg), key=lambda x: counts[x])
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != marker]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    obj = [(r-r0, c-c0, grid[r][c]) for r, c in cells]
    # Unique pixel of the object is its placement anchor.
    freq = {}
    for _, _, v in obj:
        freq[v] = freq.get(v, 0) + 1
    anchor_candidates = [(dr, dc) for dr, dc, v in obj if freq[v] == 1]
    ar, ac = anchor_candidates[0]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    for mr, mc in markers:
        for dr, dc, v in obj:
            rr, cc = mr + dr - ar, mc + dc - ac
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = v
    return out
