def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = min((v for v in counts if v != bg), key=lambda v: counts[v])
    obj = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, marker)]
    # Use the object’s unique color as its reference point; if none, use
    # the top-left occupied cell.
    cf = Counter(v for r, c, v in obj)
    unique = [(r, c) for r, c, v in obj if cf[v] == 1]
    if unique:
        ar, ac = unique[0]
    else:
        ar, ac, _ = min(obj)
    out = [row[:] for row in grid]
    for mr in range(h):
        for mc in range(w):
            if grid[mr][mc] == marker:
                for r, c, v in obj:
                    rr, cc = mr + r - ar, mc + c - ac
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = v
    return out
